CREATE OR REPLACE FUNCTION public.rcap_service_apply_onboarding_prefill(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_expected_workspace_version bigint, p_selected_value_ids uuid[], p_section_updates jsonb, p_workspace_completion integer, p_blocker_code text, p_next_action_code text, p_next_action_owner text, p_request_id uuid, p_payload_hash text)
 RETURNS TABLE(workspace_aggregate_version bigint, result jsonb, duplicate boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_workspace public.partner_onboarding%rowtype;
  v_existing public.partner_onboarding_idempotency%rowtype;
  v_value public.partner_onboarding_prefill_values%rowtype;
  v_section public.partner_onboarding_sections%rowtype;
  v_update jsonb;
  v_value_id uuid;
  v_applied uuid[] := '{}'::uuid[];
  v_conflicts uuid[] := '{}'::uuid[];
  v_skipped uuid[] := '{}'::uuid[];
  v_update_ids uuid[];
  v_new_revision bigint;
  v_applied_count integer := 0;
  v_conflict_count integer := 0;
begin
  perform public.rcap_studio_assert_prepare(p_actor_user_id,p_partner_slug);
  if p_expected_workspace_version < 1
     or p_selected_value_ids is null
     or cardinality(p_selected_value_ids) < 1
     or cardinality(p_selected_value_ids) > 200
     or p_section_updates is null
     or jsonb_typeof(p_section_updates) <> 'array'
     or p_workspace_completion not between 0 and 100
     or p_next_action_owner not in ('partner', 'legalease', 'none')
     or p_payload_hash !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'Invalid prefill apply request';
  end if;

  select *
    into v_existing
  from public.partner_onboarding_idempotency i
  where i.request_id = p_request_id
  for update;
  if found then
    if v_existing.workspace_id <> p_workspace_id
       or v_existing.operation_key <> 'prefill_apply'
       or v_existing.actor_user_id <> p_actor_user_id
       or v_existing.payload_hash <> p_payload_hash then
      raise exception using
        errcode = '23505',
        message = 'Idempotency request does not match original mutation';
    end if;
    if v_existing.result_status = 'succeeded' then
      workspace_aggregate_version := v_existing.result_workspace_version;
      result := jsonb_build_object(
        'appliedIds', '[]'::jsonb,
        'conflictIds', '[]'::jsonb,
        'skippedIds', '[]'::jsonb,
        'replayed', true
      );
      duplicate := true;
      return next;
      return;
    end if;
  end if;

  select po.*
    into v_workspace
  from public.partner_onboarding po
  where po.id = p_workspace_id
    and po.partner_slug = p_partner_slug
  for update of po;
  if not found or v_workspace.partner_record_id is null then
    raise exception using errcode = 'P0002', message = 'Onboarding workspace not found';
  end if;
  if v_workspace.aggregate_version <> p_expected_workspace_version then
    raise exception using errcode = '40001', message = 'Onboarding workspace revision conflict';
  end if;
  if v_workspace.status not in ('draft', 'commercially_blocked', 'setup_in_progress') then
    raise exception using errcode = '55000', message = 'Onboarding workspace is not eligible for prefill';
  end if;

  insert into public.partner_onboarding_idempotency (
    workspace_id,
    operation_key,
    request_id,
    actor_user_id,
    payload_hash,
    expires_at
  ) values (
    p_workspace_id,
    'prefill_apply',
    p_request_id,
    p_actor_user_id,
    p_payload_hash,
    now() + interval '24 hours'
  );

  foreach v_value_id in array p_selected_value_ids loop
    select pv.*
      into v_value
    from public.partner_onboarding_prefill_values pv
    where pv.id = v_value_id
      and pv.workspace_id = p_workspace_id
    for update;

    if not found
       or v_value.review_status <> 'approved'
       or v_value.superseded_at is not null
       or v_value.partner_review_status <> 'not_applied' then
      v_skipped := array_append(v_skipped, v_value_id);
      continue;
    end if;

    select s.*
      into v_section
    from public.partner_onboarding_sections s
    where s.workspace_id = p_workspace_id
      and s.section_key = v_value.section_key
    for update;

    if not found
       or v_section.status not in ('not_started', 'in_progress')
       or v_section.revision <> v_value.base_section_revision then
      update public.partner_onboarding_prefill_values
      set
        review_status = 'conflict',
        reviewed_by = p_actor_user_id,
        reviewed_at = now()
      where id = v_value_id;
      v_conflicts := array_append(v_conflicts, v_value_id);
      v_conflict_count := v_conflict_count + 1;
      continue;
    end if;
  end loop;

  for v_update in
    select item
    from jsonb_array_elements(p_section_updates) item
  loop
    select coalesce(array_agg(value::uuid), '{}'::uuid[])
      into v_update_ids
    from jsonb_array_elements_text(
      coalesce(v_update->'valueIds', '[]'::jsonb)
    ) value;

    if cardinality(v_update_ids) = 0
       or v_update_ids && v_conflicts
       or v_update_ids && v_skipped then
      continue;
    end if;

    select s.*
      into v_section
    from public.partner_onboarding_sections s
    where s.workspace_id = p_workspace_id
      and s.section_key = v_update->>'sectionKey'
    for update;
    if not found
       or v_section.status not in ('not_started', 'in_progress')
       or v_section.revision <> (v_update->>'expectedRevision')::bigint then
      update public.partner_onboarding_prefill_values
      set
        review_status = 'conflict',
        reviewed_by = p_actor_user_id,
        reviewed_at = now()
      where id = any(v_update_ids)
        and review_status = 'approved';
      v_conflicts := v_conflicts || v_update_ids;
      v_conflict_count := v_conflict_count + cardinality(v_update_ids);
      continue;
    end if;

    foreach v_value_id in array v_update_ids loop
      select pv.*
        into v_value
      from public.partner_onboarding_prefill_values pv
      where pv.id = v_value_id
        and pv.workspace_id = p_workspace_id
        and pv.review_status = 'approved'
      for update;

      if not found
         or not (coalesce(v_update->'baseValues', '{}'::jsonb) ? v_value_id::text)
         or public.rcap_onboarding_prefill_current_value(
           p_workspace_id, v_value.section_key, v_value.field_key
         ) is distinct from v_update->'baseValues'->v_value_id::text then
        update public.partner_onboarding_prefill_values
        set
          review_status = 'conflict',
          reviewed_by = p_actor_user_id,
          reviewed_at = now()
        where id = v_value_id
          and review_status = 'approved';
        v_conflicts := array_append(v_conflicts, v_value_id);
        v_conflict_count := v_conflict_count + 1;
      end if;
    end loop;

    if v_update_ids && v_conflicts then
      continue;
    end if;

    v_new_revision := v_section.revision + 1;
    update public.partner_onboarding_sections
    set
      response_data = v_update->'responseData',
      revision = v_new_revision,
      status = 'in_progress',
      completion_percentage = (v_update->>'completionPercentage')::integer,
      missing_required_keys = coalesce(
        array(
          select jsonb_array_elements_text(
            coalesce(v_update->'missingRequiredKeys', '[]'::jsonb)
          )
        ),
        '{}'::text[]
      ),
      first_started_at = coalesce(first_started_at, now())
    where id = v_section.id;

    if v_section.section_key = 'organization_contacts' then
      update public.partner_onboarding_contacts c
      set deleted_at = now(), revision = c.revision + 1
      where c.workspace_id = p_workspace_id
        and c.deleted_at is null
        and not exists (
          select 1
          from jsonb_array_elements(
            coalesce(v_update->'collections'->'contacts', '[]'::jsonb)
          ) item
          where item->>'stable_row_id' = c.id::text
        );
      insert into public.partner_onboarding_contacts (
        id, workspace_id, role, name, title, organization, work_email, phone
      )
      select
        (item->>'stable_row_id')::uuid,
        p_workspace_id,
        item->>'role',
        item->>'name',
        item->>'title',
        nullif(item->>'organization', ''),
        lower(item->>'work_email'),
        nullif(item->>'phone', '')
      from jsonb_array_elements(
        coalesce(v_update->'collections'->'contacts', '[]'::jsonb)
      ) item
      on conflict (id) do update
      set
        role = excluded.role,
        name = excluded.name,
        title = excluded.title,
        organization = excluded.organization,
        work_email = excluded.work_email,
        phone = excluded.phone,
        revision = public.partner_onboarding_contacts.revision + 1,
        deleted_at = null
      where public.partner_onboarding_contacts.workspace_id = p_workspace_id;
    elsif v_section.section_key = 'staff_dashboard_plan' then
      update public.partner_onboarding_planned_users u
      set deleted_at = now(), revision = u.revision + 1
      where u.workspace_id = p_workspace_id
        and u.deleted_at is null
        and not exists (
          select 1
          from jsonb_array_elements(
            coalesce(v_update->'collections'->'planned_users', '[]'::jsonb)
          ) item
          where item->>'stable_row_id' = u.id::text
        );
      insert into public.partner_onboarding_planned_users (
        id, workspace_id, name, work_email, requested_role,
        special_permissions, training_attendee
      )
      select
        (item->>'stable_row_id')::uuid,
        p_workspace_id,
        item->>'name',
        lower(item->>'work_email'),
        item->>'requested_role',
        coalesce(array(
          select jsonb_array_elements_text(
            coalesce(item->'special_permissions', '[]'::jsonb)
          )
        ), '{}'::text[]),
        coalesce((item->>'training_attendee')::boolean, false)
      from jsonb_array_elements(
        coalesce(v_update->'collections'->'planned_users', '[]'::jsonb)
      ) item
      on conflict (id) do update
      set
        name = excluded.name,
        work_email = excluded.work_email,
        requested_role = excluded.requested_role,
        special_permissions = excluded.special_permissions,
        training_attendee = excluded.training_attendee,
        revision = public.partner_onboarding_planned_users.revision + 1,
        deleted_at = null
      where public.partner_onboarding_planned_users.workspace_id = p_workspace_id;
    elsif v_section.section_key = 'support_referrals_reporting' then
      update public.partner_onboarding_report_recipients r
      set deleted_at = now(), revision = r.revision + 1
      where r.workspace_id = p_workspace_id
        and r.deleted_at is null
        and not exists (
          select 1
          from jsonb_array_elements(
            coalesce(v_update->'collections'->'report_recipients', '[]'::jsonb)
          ) item
          where item->>'stable_row_id' = r.id::text
        );
      insert into public.partner_onboarding_report_recipients (
        id, workspace_id, name, work_email
      )
      select
        (item->>'stable_row_id')::uuid,
        p_workspace_id,
        nullif(item->>'name', ''),
        lower(item->>'work_email')
      from jsonb_array_elements(
        coalesce(v_update->'collections'->'report_recipients', '[]'::jsonb)
      ) item
      on conflict (id) do update
      set
        name = excluded.name,
        work_email = excluded.work_email,
        revision = public.partner_onboarding_report_recipients.revision + 1,
        deleted_at = null
      where public.partner_onboarding_report_recipients.workspace_id = p_workspace_id;
    end if;

    update public.partner_onboarding_prefill_values
    set
      review_status = 'applied',
      applied_value_hash = proposed_value_hash,
      applied_section_revision = v_new_revision,
      applied_workspace_version = p_expected_workspace_version + 1,
      partner_review_status = 'pending',
      applied_at = now()
    where id = any(v_update_ids)
      and review_status = 'approved';

    v_applied := v_applied || v_update_ids;
    v_applied_count := v_applied_count + cardinality(v_update_ids);
  end loop;

  foreach v_value_id in array p_selected_value_ids loop
    if not (v_value_id = any(v_applied))
       and not (v_value_id = any(v_conflicts))
       and not (v_value_id = any(v_skipped)) then
      update public.partner_onboarding_prefill_values
      set
        review_status = 'conflict',
        reviewed_by = p_actor_user_id,
        reviewed_at = now()
      where id = v_value_id
        and workspace_id = p_workspace_id
        and review_status = 'approved';
      if found then
        v_conflicts := array_append(v_conflicts, v_value_id);
        v_conflict_count := v_conflict_count + 1;
      else
        v_skipped := array_append(v_skipped, v_value_id);
      end if;
    end if;
  end loop;

  if v_applied_count > 0 then
    update public.partner_onboarding
    set
      aggregate_version = aggregate_version + 1,
      completion_percentage = p_workspace_completion,
      blocker_code = p_blocker_code,
      next_action_code = p_next_action_code,
      next_action_owner = p_next_action_owner,
      last_meaningful_activity_at = now()
    where id = p_workspace_id
    returning aggregate_version into workspace_aggregate_version;

    update public.partner_onboarding_prefill_values
    set applied_workspace_version = workspace_aggregate_version
    where id = any(v_applied);

    update public.partner_onboarding_prefill_batches b
    set
      aggregate_version = aggregate_version + 1,
      status = case
        when exists (
          select 1 from public.partner_onboarding_prefill_values pv
          where pv.batch_id = b.id
            and pv.review_status in ('proposed', 'approved', 'conflict')
        ) then 'partially_applied'
        else 'applied'
      end,
      applied_at = coalesce(applied_at, now())
    where exists (
      select 1
      from public.partner_onboarding_prefill_values pv
      where pv.batch_id = b.id
        and pv.id = any(v_applied)
    );

    insert into public.partner_onboarding_activity (
      workspace_id, event_type, status_code, summary_code, owner_type,
      actor_user_id, request_id, dedupe_key
    ) values (
      p_workspace_id, 'prefill_applied', 'pending_partner_review',
      'prefill_applied', 'legalease', p_actor_user_id, p_request_id,
      p_request_id::text || ':prefill_applied'
    );

    insert into public.partner_onboarding_integration_events (
      workspace_id, partner_record_id, event_type,
      workspace_aggregate_version, workspace_status,
      completion_percentage, blocker_code, next_action_code,
      next_action_owner, target_launch_date, idempotency_key
    )
    select
      po.id, po.partner_record_id, 'rcap_onboarding_prefill_applied',
      po.aggregate_version, po.status, po.completion_percentage,
      po.blocker_code, po.next_action_code, po.next_action_owner,
      po.target_launch_date, p_request_id::text || ':prefill_applied'
    from public.partner_onboarding po
    where po.id = p_workspace_id;
  else
    workspace_aggregate_version := v_workspace.aggregate_version;
  end if;

  if v_conflict_count > 0 then
    insert into public.partner_onboarding_activity (
      workspace_id, event_type, status_code, summary_code, owner_type,
      actor_user_id, request_id, dedupe_key
    ) values (
      p_workspace_id, 'prefill_apply_conflict', 'conflict',
      'prefill_apply_conflict', 'legalease', p_actor_user_id, p_request_id,
      p_request_id::text || ':prefill_apply_conflict'
    );
  end if;

  result := jsonb_build_object(
    'appliedIds', to_jsonb(v_applied),
    'conflictIds', to_jsonb(v_conflicts),
    'skippedIds', to_jsonb(v_skipped)
  );
  update public.partner_onboarding_idempotency
  set
    result_status = 'succeeded',
    result_workspace_version = workspace_aggregate_version,
    completed_at = now()
  where request_id = p_request_id;
  duplicate := false;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.rcap_service_compensate_real_launch(p_slug text, p_actor uuid, p_operation uuid, p_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare e public.rcap_launch_operation_events%rowtype; begin
 perform public.rcap_service_assert_internal_actor(p_actor);
 select ev.* into strict e from public.rcap_launch_operation_events ev join public.partner_onboarding w on w.id=ev.workspace_id where ev.partner_slug=p_slug and ev.operation_id=p_operation and ev.step='prepared' and ev.actor_auth_user_id=p_actor and ev.snapshot_hash=p_hash and ev.evidence->>'mode'='real' for update of w;
 if exists(select 1 from public.rcap_launch_operation_events where operation_id=p_operation and step='complete') then raise exception 'completed operation cannot compensate'; end if;
 if exists(select 1 from public.partner_onboarding where id=e.workspace_id and rcap_launch_operation_id=p_operation) then
 update public.partner_records set onboarding_status=e.evidence->'previousLegacyOnboarding'->>'onboarding_status',onboarding_completed_at=(e.evidence->'previousLegacyOnboarding'->>'onboarding_completed_at')::timestamptz where partner_slug=p_slug;
 end if;
 -- Retain the operation marker so an uncertain failure cannot expose a page.
 update public.partner_onboarding set status=e.evidence->'previousPublication'->>'status',landing_page_ready=false,internal_approved_at=(e.evidence->'previousPublication'->>'internal_approved_at')::timestamptz,launched_at=(e.evidence->'previousPublication'->>'launched_at')::timestamptz where id=e.workspace_id and rcap_launch_operation_id=p_operation;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.rcap_service_compensate_synthetic_launch(p_slug text, p_actor uuid, p_operation uuid, p_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_event public.rcap_launch_operation_events%rowtype; begin
 perform public.rcap_service_assert_internal_actor(p_actor);
 select e.* into strict v_event from public.rcap_launch_operation_events e join public.partner_onboarding po on po.id=e.workspace_id where e.partner_slug=p_slug and e.operation_id=p_operation and e.step='prepared' and e.actor_auth_user_id=p_actor and e.snapshot_hash=p_hash for update of po;
 if exists(select 1 from public.rcap_launch_operation_events where operation_id=p_operation and step='complete') then raise exception 'completed operation cannot compensate'; end if;
 if not exists(select 1 from public.rcap_launch_operation_events where operation_id=p_operation and step='publication_staged') then return true; end if;
 update public.partner_onboarding set status=v_event.evidence->'previousPublication'->>'status',landing_page_ready=(v_event.evidence->'previousPublication'->>'landing_page_ready')::boolean,internal_approved_at=(v_event.evidence->'previousPublication'->>'internal_approved_at')::timestamptz,launched_at=(v_event.evidence->'previousPublication'->>'launched_at')::timestamptz where id=v_event.workspace_id;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.rcap_service_configure_launch_capacity(p_slug text, p_actor uuid, p_document uuid, p_hash text, p_screenings integer, p_packets integer, p_reference text, p_request uuid, p_version bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare w public.partner_onboarding%rowtype; old public.rcap_launch_capacity_events%rowtype; previous jsonb; begin
 perform public.rcap_service_assert_internal_actor(p_actor);
 select * into strict w from public.partner_onboarding where partner_slug=p_slug for update;
 select * into old from public.rcap_launch_capacity_events where workspace_id=w.id and request_id=p_request;
 if found then if old.actor_auth_user_id<>p_actor or old.document_id<>p_document or old.document_hash<>p_hash or old.screenings_allowed<>p_screenings or old.packet_cap<>p_packets or old.authority_reference<>p_reference then raise exception 'capacity request binding conflict'; end if;return true;end if;
 if w.status='live' or w.landing_page_ready or w.aggregate_version<>p_version then raise exception 'publication or source changed'; end if;
 if exists(select 1 from public.rcap_launch_operation_events e where e.workspace_id=w.id and e.step='prepared' and not exists(select 1 from public.rcap_launch_operation_events t where t.operation_id=e.operation_id and t.step in ('complete','held','failed'))) then raise exception 'launch in progress'; end if;
 perform 1 from public.partner_entitlement where partner_slug=p_slug for update;
 perform 1 from public.partner_packet_entitlement where partner_id=w.partner_record_id and entitlement_scope='sponsored_packets' and expires_at is null for update;
 previous:=jsonb_build_object('screening',(select to_jsonb(e) from public.partner_entitlement e where e.partner_slug=p_slug),'packet',(select to_jsonb(e) from public.partner_packet_entitlement e where e.partner_id=w.partner_record_id and e.entitlement_scope='sponsored_packets' and e.expires_at is null));
 insert into public.rcap_launch_capacity_events(workspace_id,actor_auth_user_id,document_id,document_hash,screenings_allowed,packet_cap,authority_reference,request_id,previous_capacity) values(w.id,p_actor,p_document,p_hash,p_screenings,p_packets,p_reference,p_request,previous);
 insert into public.partner_entitlement(partner_slug,screenings_allowed,contract_note) values(p_slug,p_screenings,p_reference) on conflict(partner_slug) do update set screenings_allowed=excluded.screenings_allowed,contract_note=excluded.contract_note;
 if exists(select 1 from public.partner_packet_entitlement where partner_id=w.partner_record_id and entitlement_scope='sponsored_packets' and expires_at is null) then
 update public.partner_packet_entitlement set packet_cap=p_packets where partner_id=w.partner_record_id and entitlement_scope='sponsored_packets' and expires_at is null;
 else insert into public.partner_packet_entitlement(partner_id,entitlement_scope,packet_cap,contract_note) values(w.partner_record_id,'sponsored_packets',p_packets,p_reference);end if;
 update public.partner_onboarding set aggregate_version=aggregate_version+1 where id=w.id;
 update public.partner_onboarding_launch_checks set invalidated_at=now(),invalidated_reason='Documented allocation changed' where workspace_id=w.id;
 update public.partner_onboarding_launch_approvals set invalidated_at=now() where workspace_id=w.id;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.rcap_service_generate_onboarding_artifact_version(p_partner_slug text, p_actor_user_id uuid, p_workspace_id uuid, p_artifact_type text, p_request_id uuid, p_source_workspace_version bigint, p_source_section_revisions jsonb, p_source_asset_versions jsonb, p_normalized_snapshot jsonb, p_snapshot_hash text, p_generator_version text, p_rendered_content jsonb, p_generation_status text, p_generation_error_code text)
 RETURNS TABLE(version_id uuid, version_number integer, duplicate boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_artifact public.partner_onboarding_artifacts%rowtype;
  v_existing public.partner_onboarding_artifact_versions%rowtype;
  v_next integer;
  v_new public.partner_onboarding_artifact_versions%rowtype;
begin
  if p_generation_status not in ('succeeded', 'failed') then
    raise exception 'invalid_generation_status' using errcode = '22023';
  end if;

  select a.* into v_artifact
  from public.partner_onboarding_artifacts a
  join public.partner_onboarding po on po.id = a.workspace_id
  where a.workspace_id = p_workspace_id
    and a.artifact_type = p_artifact_type
    and po.partner_slug = p_partner_slug
  for update of a;

  if v_artifact.id is null then
    raise exception 'artifact_not_found' using errcode = 'P0002';
  end if;

  if v_artifact.lifecycle_status = 'unavailable_in_release' then
    raise exception 'artifact_generator_unavailable' using errcode = '0A000';
  end if;

  -- Idempotency: the same request id returns the version it already created.
  select v.* into v_existing
  from public.partner_onboarding_artifact_versions v
  where v.artifact_id = v_artifact.id
    and v.request_id = p_request_id;

  if v_existing.id is not null then
    version_id := v_existing.id;
    version_number := v_existing.version_number;
    duplicate := true;
    return next;
    return;
  end if;

  select coalesce(max(v.version_number), 0) + 1 into v_next
  from public.partner_onboarding_artifact_versions v
  where v.artifact_id = v_artifact.id;

  insert into public.partner_onboarding_artifact_versions (
    artifact_id, workspace_id, version_number,
    source_workspace_version, source_section_revisions, source_asset_versions,
    normalized_snapshot, snapshot_hash, generator_version, rendered_content,
    generation_status, generation_error_code,
    approval_status, generated_by, request_id
  )
  values (
    v_artifact.id, p_workspace_id, v_next,
    p_source_workspace_version, p_source_section_revisions, p_source_asset_versions,
    p_normalized_snapshot, p_snapshot_hash, p_generator_version, p_rendered_content,
    p_generation_status, p_generation_error_code,
    case when p_generation_status = 'failed' then 'generation_failed' else 'draft' end,
    p_actor_user_id, p_request_id
  )
  returning * into v_new;

  -- A superseded prior version stays readable in history; it is never rewritten.
  update public.partner_onboarding_artifact_versions
  set approval_status = 'superseded',
      superseded_at = now()
  where artifact_id = v_artifact.id
    and id <> v_new.id
    and approval_status <> 'generation_failed'
    and superseded_at is null;

  update public.partner_onboarding_artifacts
  set current_version_id = v_new.id,
      lifecycle_status = case
        when p_generation_status = 'failed' then 'generation_failed'
        else 'draft'
      end
  where id = v_artifact.id;

  insert into public.partner_onboarding_activity (
    workspace_id, event_type, owner_type, summary_code, status_code,
    artifact_version_id
  )
  values (
    p_workspace_id,
    case when p_generation_status = 'failed'
      then 'artifact_generation_failed'
      else 'artifact_generated'
    end,
    'legalease',
    p_artifact_type,
    p_generation_status,
    v_new.id
  );

  version_id := v_new.id;
  version_number := v_new.version_number;
  duplicate := false;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.rcap_service_invalidate_affected_launch_checks(p_partner_slug text, p_workspace_id uuid, p_check_keys text[], p_reason text)
 RETURNS TABLE(invalidated_count integer)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_count integer;
begin
  if p_reason is null or char_length(btrim(p_reason)) = 0 then
    raise exception 'invalidation_reason_required' using errcode = '22023';
  end if;

  with updated as (
    update public.partner_onboarding_launch_checks c
    set invalidated_at = now(),
        invalidated_reason = p_reason
    from public.partner_onboarding po
    where c.workspace_id = p_workspace_id
      and po.id = c.workspace_id
      and po.partner_slug = p_partner_slug
      and c.invalidated_at is null
      and c.status in ('passing', 'waived', 'not_applicable')
      and c.check_key = any(p_check_keys)
    returning c.id
  )
  select count(*)::integer into v_count from updated;

  if v_count > 0 then
    insert into public.partner_onboarding_activity (
      workspace_id, event_type, owner_type, summary_code, status_code
    )
    values (
      p_workspace_id, 'launch_check_invalidated', 'system',
      'affected_checks',
      'source_changed'
    );
  end if;

  invalidated_count := v_count;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.rcap_service_invalidate_onboarding_artifact_version(p_partner_slug text, p_artifact_version_id uuid, p_current_snapshot_hash text, p_drift_fields text[])
 RETURNS TABLE(invalidated boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_updated public.partner_onboarding_artifact_versions%rowtype;
  v_artifact_type text;
begin
  update public.partner_onboarding_artifact_versions v
  set source_drift_invalidated_at = now(),
      source_drift_fields = p_drift_fields,
      invalidated_against_snapshot_hash = p_current_snapshot_hash
  from public.partner_onboarding po
  where v.id = p_artifact_version_id
    and po.id = v.workspace_id
    and po.partner_slug = p_partner_slug
    and v.generation_status = 'succeeded'
    and v.source_drift_invalidated_at is null
    and v.snapshot_hash <> p_current_snapshot_hash
  returning v.* into v_updated;

  if v_updated.id is null then
    invalidated := false;
    return next;
    return;
  end if;

  select a.artifact_type into v_artifact_type
  from public.partner_onboarding_artifacts a
  where a.id = v_updated.artifact_id;

  insert into public.partner_onboarding_activity (
    workspace_id, event_type, owner_type, summary_code, status_code,
    artifact_version_id
  )
  values (
    v_updated.workspace_id,
    'artifact_approval_invalidated',
    'system',
    v_artifact_type,
    'source_changed',
    v_updated.id
  )
  on conflict do nothing;

  invalidated := true;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.rcap_service_invalidate_onboarding_launch_checks(p_partner_slug text, p_workspace_id uuid, p_invalidate_partner_owned boolean, p_reason text)
 RETURNS TABLE(invalidated_count integer)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_count integer;
begin
  if p_reason is null or char_length(btrim(p_reason)) = 0 then
    raise exception 'invalidation_reason_required' using errcode = '22023';
  end if;

  with updated as (
    update public.partner_onboarding_launch_checks c
    set invalidated_at = now(),
        invalidated_reason = p_reason
    from public.partner_onboarding po
    where c.workspace_id = p_workspace_id
      and po.id = c.workspace_id
      and po.partner_slug = p_partner_slug
      and c.invalidated_at is null
      and c.status in ('passing', 'waived', 'not_applicable')
      and (p_invalidate_partner_owned or c.owner_type = 'legalease')
    returning c.id
  )
  select count(*)::integer into v_count from updated;

  if v_count > 0 then
    insert into public.partner_onboarding_activity (
      workspace_id, event_type, owner_type, summary_code, status_code
    )
    values (
      p_workspace_id, 'launch_check_invalidated', 'system',
      case when p_invalidate_partner_owned then 'all_owners' else 'legalease_only' end,
      'source_changed'
    );
  end if;

  invalidated_count := v_count;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.rcap_service_record_commercial_authority(p_slug text, p_actor uuid, p_kind text, p_document uuid, p_hash text, p_reference text, p_expires timestamp with time zone, p_packet uuid, p_request uuid, p_version bigint, p_reconcile boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare w public.partner_onboarding%rowtype; a uuid; mode text; old public.rcap_commercial_authorizations%rowtype; begin
 perform public.rcap_service_assert_internal_actor(p_actor);
 select * into strict w from public.partner_onboarding where partner_slug=p_slug for update;
 select * into old from public.rcap_commercial_authorizations where workspace_id=w.id and request_id=p_request;
 if found then
 if old.actor_auth_user_id<>p_actor or old.kind<>p_kind or old.document_id<>p_document or old.document_hash<>p_hash or old.authority_reference<>p_reference or old.expires_at<>p_expires or old.packet_entitlement_id<>p_packet then raise exception 'request binding conflict'; end if; return old.id; end if;
 if w.aggregate_version<>p_version or w.status='live' or not p_reconcile then raise exception 'explicit current-source reconciliation required'; end if;
 if exists(select 1 from public.rcap_launch_operation_events e where e.workspace_id=w.id and e.step='prepared' and not exists(select 1 from public.rcap_launch_operation_events t where t.operation_id=e.operation_id and t.step in ('complete','held','failed'))) then raise exception 'launch in progress'; end if;
 select response_data->>'participant_access_model' into strict mode from public.partner_onboarding_sections where workspace_id=w.id and section_key='access_sponsorship_capacity';
 insert into public.rcap_commercial_authorizations(workspace_id,kind,document_id,document_hash,authority_reference,access_mode,packet_entitlement_id,actor_auth_user_id,expires_at,request_id)
 values(w.id,p_kind,p_document,p_hash,p_reference,mode,p_packet,p_actor,p_expires,p_request) returning id into a;
 -- Reconcile access/provisioning from documented authority. Never write payment.
 update public.partner_records set access_mode=mode,provisioning_status='provisioned' where id=w.partner_record_id;
 update public.partner_onboarding set aggregate_version=aggregate_version+1 where id=w.id;
 -- A changed commercial/activation source requires renewed exact-source approvals.
 update public.partner_onboarding_launch_checks set invalidated_at=now(),invalidated_reason='Commercial authorization and activation reconciled' where workspace_id=w.id;
 update public.partner_onboarding_launch_approvals set invalidated_at=now() where workspace_id=w.id;
 return a;
end $function$

CREATE OR REPLACE FUNCTION public.rcap_service_record_onboarding_launch_approval(p_partner_slug text, p_actor_user_id uuid, p_reviewer_type text, p_workspace_id uuid, p_approval_type text, p_decision text, p_comments text, p_request_id uuid)
 RETURNS TABLE(approval_id uuid, duplicate boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_partner_record_id uuid;
  v_existing uuid;
  v_row public.partner_onboarding_launch_approvals%rowtype;
  v_check_key text;
  v_owner text;
begin
  if p_decision not in ('approve', 'withdraw') then
    raise exception 'invalid_decision' using errcode = '22023';
  end if;

  if p_approval_type = 'partner_launch_approval' then
    v_check_key := 'partner_launch_approval_received';
    v_owner := 'partner';
  elsif p_approval_type = 'legalease_final_review' then
    v_check_key := 'legalease_final_review_complete';
    v_owner := 'legalease';
  else
    raise exception 'invalid_approval_type' using errcode = '22023';
  end if;

  if p_reviewer_type <> v_owner then
    raise exception 'reviewer_does_not_own_approval' using errcode = '42501';
  end if;

  select po.partner_record_id into v_partner_record_id
  from public.partner_onboarding po
  where po.id = p_workspace_id
    and po.partner_slug = p_partner_slug;

  if v_partner_record_id is null then
    raise exception 'workspace_not_found' using errcode = 'P0002';
  end if;

  select a.id into v_existing
  from public.partner_onboarding_launch_approvals a
  where a.workspace_id = p_workspace_id
    and a.request_id = p_request_id;

  if v_existing is not null then
    approval_id := v_existing;
    duplicate := true;
    return next;
    return;
  end if;

  insert into public.partner_onboarding_launch_approvals (
    workspace_id, approval_type, reviewer_type, reviewer_user_id,
    decision, comments, request_id
  )
  values (
    p_workspace_id, p_approval_type, p_reviewer_type, p_actor_user_id,
    p_decision, p_comments, p_request_id
  )
  returning * into v_row;

  insert into public.partner_onboarding_launch_checks (
    workspace_id, partner_record_id, check_key, category, owner_type,
    determination, blocking, status, evidence_summary, evidence_reference,
    checked_at, checked_by, request_id
  )
  values (
    p_workspace_id, v_partner_record_id, v_check_key, 'approvals', v_owner,
    'manual', true,
    case when p_decision = 'approve' then 'passing' else 'failing' end,
    case when p_decision = 'approve'
      then 'Launch approval recorded.'
      else 'Launch approval withdrawn.'
    end,
    'launch_approval',
    case when p_decision = 'approve' then now() else null end,
    case when p_decision = 'approve' then p_actor_user_id else null end,
    p_request_id
  )
  on conflict (workspace_id, check_key) do update
  set status = excluded.status,
      evidence_summary = excluded.evidence_summary,
      checked_at = excluded.checked_at,
      checked_by = excluded.checked_by,
      invalidated_at = null,
      invalidated_reason = null,
      request_id = excluded.request_id;

  insert into public.partner_onboarding_activity (
    workspace_id, event_type, owner_type, summary_code, status_code
  )
  values (
    p_workspace_id, 'launch_approval_recorded',
    case when p_reviewer_type = 'partner' then 'partner' else 'legalease' end,
    p_approval_type, p_decision
  );

  approval_id := v_row.id;
  duplicate := false;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.rcap_service_record_onboarding_launch_check(p_partner_slug text, p_actor_user_id uuid, p_reviewer_type text, p_workspace_id uuid, p_check_key text, p_category text, p_owner_type text, p_blocking boolean, p_status text, p_evidence_summary text, p_request_id uuid)
 RETURNS TABLE(check_id uuid, check_status text, duplicate boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_partner_record_id uuid;
  v_existing public.partner_onboarding_launch_checks%rowtype;
  v_row public.partner_onboarding_launch_checks%rowtype;
begin
  if p_reviewer_type not in ('legalease', 'partner') then
    raise exception 'invalid_reviewer_type' using errcode = '22023';
  end if;
  if p_status not in ('passing', 'needs_review', 'waived', 'not_applicable') then
    raise exception 'invalid_launch_check_status' using errcode = '22023';
  end if;
  -- Only LegalEase may waive a check or mark one not applicable.
  if p_reviewer_type = 'partner'
     and p_status in ('waived', 'not_applicable') then
    raise exception 'waiver_requires_legalease' using errcode = '42501';
  end if;
  -- A reviewer may only decide a check its own side owns.
  if p_reviewer_type <> p_owner_type then
    raise exception 'reviewer_does_not_own_check' using errcode = '42501';
  end if;

  select po.partner_record_id into v_partner_record_id
  from public.partner_onboarding po
  where po.id = p_workspace_id
    and po.partner_slug = p_partner_slug;

  if v_partner_record_id is null then
    raise exception 'workspace_not_found' using errcode = 'P0002';
  end if;

  select c.* into v_existing
  from public.partner_onboarding_launch_checks c
  where c.workspace_id = p_workspace_id
    and c.request_id = p_request_id;

  if v_existing.id is not null then
    check_id := v_existing.id;
    check_status := v_existing.status;
    duplicate := true;
    return next;
    return;
  end if;

  insert into public.partner_onboarding_launch_checks (
    workspace_id, partner_record_id, check_key, category, owner_type,
    determination, blocking, status, evidence_summary, evidence_reference,
    checked_at, checked_by, request_id
  )
  values (
    p_workspace_id, v_partner_record_id, p_check_key, p_category, p_owner_type,
    'manual', p_blocking, p_status, p_evidence_summary, 'manual_review',
    now(), p_actor_user_id, p_request_id
  )
  on conflict (workspace_id, check_key) do update
  set status = excluded.status,
      evidence_summary = excluded.evidence_summary,
      checked_at = excluded.checked_at,
      checked_by = excluded.checked_by,
      blocking = excluded.blocking,
      category = excluded.category,
      -- Recording a fresh decision clears the previous invalidation.
      invalidated_at = null,
      invalidated_reason = null,
      request_id = excluded.request_id
  returning * into v_row;

  insert into public.partner_onboarding_activity (
    workspace_id, event_type, owner_type, summary_code, status_code
  )
  values (
    p_workspace_id,
    'launch_check_recorded',
    case when p_reviewer_type = 'partner' then 'partner' else 'legalease' end,
    p_check_key,
    p_status
  );

  check_id := v_row.id;
  check_status := v_row.status;
  duplicate := false;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.rcap_service_record_onboarding_launch_readiness(p_partner_slug text, p_workspace_id uuid, p_state text)
 RETURNS TABLE(changed boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_updated public.partner_onboarding%rowtype;
begin
  if p_state not in ('ready', 'not_ready') then
    raise exception 'invalid_readiness_state' using errcode = '22023';
  end if;

  update public.partner_onboarding po
  set launch_readiness_state = p_state
  where po.id = p_workspace_id
    and po.partner_slug = p_partner_slug
    and po.launch_readiness_state is distinct from p_state
  returning * into v_updated;

  if v_updated.id is null then
    changed := false;
    return next;
    return;
  end if;

  insert into public.partner_onboarding_activity (
    workspace_id, event_type, owner_type, summary_code, status_code
  )
  values (
    p_workspace_id,
    case when p_state = 'ready'
      then 'launch_readiness_achieved'
      else 'launch_readiness_lost'
    end,
    'system',
    'launch_readiness',
    p_state
  );

  changed := true;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.rcap_service_record_signed_agreement(p_slug text, p_actor uuid, p_expected_version bigint, p_request uuid, p_agreement_type text, p_asset uuid, p_new_asset boolean, p_object_path text, p_filename text, p_media_type text, p_extension text, p_byte_size bigint, p_sha256 text, p_effective_date date, p_review_reason text, p_confirmed boolean)
 RETURNS TABLE(workspace_version bigint, document_id uuid, duplicate boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  w public.partner_onboarding%rowtype;
  prior public.rcap_signed_agreement_receipts%rowtype;
  doc public.partner_onboarding_assets%rowtype;
  previous_doc public.partner_onboarding_assets%rowtype;
  previous_agreement jsonb;
  contract_changed boolean;
begin
  perform public.rcap_service_assert_internal_actor(p_actor);
  if p_confirmed is distinct from true or p_new_asset is null
     or p_request is null or p_asset is null or p_agreement_type is null
     or p_sha256 is null or p_agreement_type not in ('order_form','master_services_agreement')
     or p_effective_date is null or p_effective_date>current_date
     or length(btrim(coalesce(p_review_reason,''))) not between 10 and 5000
     or p_sha256 !~ '^[a-f0-9]{64}$' then
    raise exception 'A reviewed, executed agreement and signed document are required' using errcode='22023';
  end if;

  select * into strict w from public.partner_onboarding
    where partner_slug=p_slug for update;
  select * into prior from public.rcap_signed_agreement_receipts where id=p_request;
  if found then
    if prior.workspace_id<>w.id or prior.partner_slug<>p_slug
       or prior.actor_auth_user_id<>p_actor or prior.agreement_type<>p_agreement_type
       or (not p_new_asset and prior.asset_id is distinct from p_asset)
       or prior.asset_sha256<>p_sha256
       or prior.effective_date<>p_effective_date
       or prior.reviewed_reason<>btrim(p_review_reason) then
       raise exception 'Executed agreement request was reused with different inputs' using errcode='23505';
    end if;
    return query select prior.workspace_version,prior.asset_id,true;
    return;
  end if;

  if w.aggregate_version is distinct from p_expected_version
     or w.status in ('live','paused','closed')
     or w.commercial_gate_status='blocked' then
    -- A stale user snapshot is not a retryable database serialization failure.
    raise exception 'Current unpublished agreement workspace required' using errcode='55000';
  end if;

  if p_new_asset then
    if not exists(select 1 from storage.objects o join storage.buckets b on b.id=o.bucket_id
      where o.bucket_id='rcap-partner-onboarding-private' and o.name=p_object_path and b.public=false) then
      raise exception 'Executed copy is absent from private storage' using errcode='55000';
    end if;
    if p_media_type is null or p_extension is null
       or p_object_path is null or p_filename is null or p_byte_size is null
       or p_media_type not in (
      'application/pdf',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
    ) or (p_media_type='application/pdf' and p_extension<>'pdf')
       or (p_media_type<>'application/pdf' and p_extension<>'docx')
       or p_byte_size<1 or p_byte_size>20971520
       or length(p_filename) not between 1 and 240
       or p_object_path<>('partners/'||w.partner_record_id::text||
       '/onboarding/'||w.id::text||'/procurement_document/'||p_asset::text||'.'||p_extension)
    then raise exception 'Signed file identity or document type is invalid' using errcode='22023';
    end if;
    select * into previous_doc from public.partner_onboarding_assets
      where workspace_id=w.id and category='procurement_document'
        and lifecycle_status in ('active','pending_review') and deleted_at is null for update;
    if found then
      -- Retain the original object and agreement evidence; only its current
      -- procurement slot is superseded by this executed copy.
      update public.partner_onboarding_assets set lifecycle_status='superseded',
        updated_at=now() where id=previous_doc.id;
    end if;
    insert into public.partner_onboarding_assets(
      id,workspace_id,partner_record_id,category,object_path,original_filename,
      safe_filename,media_type,file_extension,byte_size,sha256_hex,
      lifecycle_status,review_status,review_reason,uploaded_by
    ) values(
      p_asset,w.id,w.partner_record_id,'procurement_document',p_object_path,
      p_filename,'signed-agreement.'||p_extension,p_media_type,p_extension,
      p_byte_size,p_sha256,'active','approved',
      'Executed signed agreement inspected and certified by Platform Admin',p_actor
    );
  end if;

  select * into doc from public.partner_onboarding_assets
    where id=p_asset and workspace_id=w.id
      and category='procurement_document' and deleted_at is null
      and lifecycle_status='active' and review_status='approved'
      and sha256_hex=p_sha256 for update;
  if not found then
    raise exception 'An active, approved, matching signed agreement document is required' using errcode='55000';
  end if;
  if doc.media_type not in ('application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document')
     or not exists(select 1 from storage.objects o join storage.buckets b on b.id=o.bucket_id
       where o.bucket_id=doc.bucket_id and o.name=doc.object_path
         and b.id='rcap-partner-onboarding-private' and b.public=false) then
    raise exception 'The executed document must exist in private storage' using errcode='55000';
  end if;

  select to_jsonb(a) into previous_agreement from public.partner_onboarding_agreements a
    where a.workspace_id=w.id and a.agreement_type=p_agreement_type;
  contract_changed := previous_agreement is null
    or previous_agreement->>'status' is distinct from 'executed'
    or previous_agreement->>'finalized_asset_id' is distinct from doc.id::text
    or previous_agreement->>'effective_date' is distinct from p_effective_date::text
    or previous_agreement->>'signed_asset_sha256' is distinct from p_sha256
    or previous_agreement->>'signed_receipt_id' is null;
  insert into public.rcap_signed_agreement_receipts(
    id,workspace_id,partner_slug,actor_auth_user_id,agreement_type,asset_id,
    asset_sha256,effective_date,reviewed_reason,workspace_version,previous_agreement
  ) values(p_request,w.id,p_slug,p_actor,p_agreement_type,doc.id,
    p_sha256,p_effective_date,btrim(p_review_reason),w.aggregate_version+1,previous_agreement);

  insert into public.partner_onboarding_agreements(
    workspace_id,agreement_type,status,is_required,partner_safe_detail,
    finalized_asset_id,effective_date,recorded_by,recorded_at,signed_receipt_id,signed_asset_sha256
  ) values(
    w.id,p_agreement_type,'executed',true,
    'Executed agreement verified by LegalEase',doc.id,
    p_effective_date,p_actor,now(),p_request,p_sha256
  ) on conflict(workspace_id,agreement_type) do update set
    status='executed',is_required=true,partner_safe_detail=excluded.partner_safe_detail,
    finalized_asset_id=excluded.finalized_asset_id,
    effective_date=excluded.effective_date,
    recorded_by=excluded.recorded_by,recorded_at=excluded.recorded_at,
    signed_receipt_id=excluded.signed_receipt_id,
    signed_asset_sha256=excluded.signed_asset_sha256;

  perform set_config('rcap.agreement_projection',p_request::text,true);
  update public.partner_onboarding set agreement_status='signed',
    agreement_date=p_effective_date,aggregate_version=aggregate_version+1,
    last_meaningful_activity_at=now()
    where id=w.id returning aggregate_version into workspace_version;
  perform set_config('rcap.agreement_projection','',true);



  -- Preserve unrelated staff-training and operational attestations. Only
  -- launch decisions tied to changed contractual authority are renewed.
  if contract_changed then
  update public.partner_onboarding_launch_checks set
    invalidated_at=now(),invalidated_reason='Executed agreement changed'
    where workspace_id=w.id
      and check_key in ('legalease_final_review_complete','partner_launch_approval_received')
      and invalidated_at is null;
  update public.partner_onboarding_launch_approvals set
    invalidated_at=now() where workspace_id=w.id and invalidated_at is null;
  end if;

  document_id:=doc.id;
  duplicate:=false;
  return next;
end $function$

CREATE OR REPLACE FUNCTION public.rcap_service_retire_onboarding_artifact(p_partner_slug text, p_actor_user_id uuid, p_artifact_version_id uuid, p_reason text, p_request_id uuid)
 RETURNS TABLE(superseded boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_workspace uuid; v_artifact uuid;
begin
  if not exists(select 1 from public.partner_users u where u.auth_user_id=p_actor_user_id and u.role='internal_admin' and u.status='active' and u.partner_slug is null) then raise exception 'internal_admin_required' using errcode='42501'; end if;
  if length(btrim(p_reason))<10 or length(p_reason)>2000 or p_request_id is null then raise exception 'specific_reason_required'; end if;
  select v.workspace_id,v.artifact_id into v_workspace,v_artifact from public.partner_onboarding_artifact_versions v join public.partner_onboarding po on po.id=v.workspace_id where v.id=p_artifact_version_id and po.partner_slug=p_partner_slug for update of v,po;
  if v_workspace is null then raise exception 'version_not_found'; end if;
  if exists(select 1 from public.partner_onboarding_artifact_reviews where artifact_version_id=p_artifact_version_id and request_id=p_request_id and (reviewer_user_id<>p_actor_user_id or comments<>'Version retirement: '||btrim(p_reason))) then raise exception 'idempotency_payload_conflict'; end if;
  -- Preserve the actual reviewer, reason and request identity in the existing
  -- append-only review ledger, then retire and clear only this current pointer.
  if not exists(select 1 from public.partner_onboarding_artifact_reviews where artifact_version_id=p_artifact_version_id and request_id=p_request_id) then
    insert into public.partner_onboarding_artifact_reviews(artifact_version_id,workspace_id,reviewer_type,reviewer_user_id,decision,comments,request_id)
      values(p_artifact_version_id,v_workspace,'legalease',p_actor_user_id,'request_changes','Version retirement: '||btrim(p_reason),p_request_id);
  end if;
  perform public.rcap_service_supersede_onboarding_artifact_version(p_partner_slug,p_actor_user_id,p_artifact_version_id);
  update public.partner_onboarding_artifacts set current_version_id=null,lifecycle_status='not_generated' where id=v_artifact and current_version_id=p_artifact_version_id;
  superseded:=true; return next;
end; $function$

CREATE OR REPLACE FUNCTION public.rcap_service_review_launch_package(p_partner_slug text, p_actor_user_id uuid, p_request_id uuid, p_workspace_version bigint, p_versions jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_workspace public.partner_onboarding%rowtype;
  v_item jsonb;
  v_version public.partner_onboarding_artifact_versions%rowtype;
  v_count integer;
begin
  if not exists(select 1 from public.partner_users u where u.auth_user_id=p_actor_user_id and u.role='internal_admin' and u.status='active' and u.partner_slug is null) then
    raise exception 'internal_admin_required' using errcode='42501';
  end if;
  select * into v_workspace from public.partner_onboarding where partner_slug=p_partner_slug for update;
  if v_workspace.id is null or v_workspace.aggregate_version <> p_workspace_version then raise exception 'stale_workspace'; end if;
  if p_request_id is null then raise exception 'request_identity_required'; end if;
  if jsonb_typeof(p_versions)<>'array' or jsonb_array_length(p_versions)<>5 then raise exception 'exact_package_required'; end if;
  select count(distinct item->>'id') into v_count from jsonb_array_elements(p_versions) item;
  if v_count<>5 then raise exception 'duplicate_version'; end if;
  if exists(select 1 from public.partner_onboarding_artifact_reviews r where r.workspace_id=v_workspace.id and r.request_id=p_request_id and
    (r.reviewer_user_id<>p_actor_user_id or r.reviewer_type<>'legalease' or r.decision<>'approve' or not exists(select 1 from jsonb_array_elements(p_versions) item where (item->>'id')::uuid=r.artifact_version_id))) then raise exception 'idempotency_payload_conflict'; end if;
  -- Lock and validate the entire package before any review is recorded.
  for v_item in select * from jsonb_array_elements(p_versions) loop
    select v.* into v_version from public.partner_onboarding_artifact_versions v
      join public.partner_onboarding_artifacts a on a.id=v.artifact_id
      where v.id=(v_item->>'id')::uuid and v.workspace_id=v_workspace.id
      and a.current_version_id=v.id and a.artifact_type in ('implementation_brief','operations_escalation_plan','dashboard_user_reporting_matrix','staff_quick_start_guide','co_branded_page_configuration')
      for update of v,a;
    if v_version.id is null or v_version.snapshot_hash<>v_item->>'snapshotHash'
      or v_version.generation_status<>'succeeded' or v_version.approval_status='superseded'
      or v_version.superseded_at is not null or v_version.source_drift_invalidated_at is not null then raise exception 'package_version_changed'; end if;
  end loop;
  for v_item in select * from jsonb_array_elements(p_versions) loop
    perform public.rcap_service_review_onboarding_artifact(p_partner_slug,p_actor_user_id,'legalease',(v_item->>'id')::uuid,'approve','Reviewed as part of the exact launch package',null,p_request_id);
  end loop;
  return true;
end; $function$

CREATE OR REPLACE FUNCTION public.rcap_service_review_onboarding_artifact(p_partner_slug text, p_actor_user_id uuid, p_reviewer_type text, p_artifact_version_id uuid, p_decision text, p_comments text, p_partner_visible_instructions text, p_request_id uuid)
 RETURNS TABLE(approval_status text, partner_review_status text, duplicate boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_version public.partner_onboarding_artifact_versions%rowtype;
  v_artifact public.partner_onboarding_artifacts%rowtype;
  v_existing uuid;
begin
  if p_reviewer_type not in ('legalease', 'partner') then
    raise exception 'invalid_reviewer_type' using errcode = '22023';
  end if;
  if p_decision not in ('approve', 'request_changes', 'reject') then
    raise exception 'invalid_decision' using errcode = '22023';
  end if;

  select v.* into v_version
  from public.partner_onboarding_artifact_versions v
  join public.partner_onboarding po on po.id = v.workspace_id
  where v.id = p_artifact_version_id
    and po.partner_slug = p_partner_slug
  for update of v;

  if v_version.id is null then
    raise exception 'artifact_version_not_found' using errcode = 'P0002';
  end if;

  select a.* into v_artifact
  from public.partner_onboarding_artifacts a
  where a.id = v_version.artifact_id;

  select r.id into v_existing
  from public.partner_onboarding_artifact_reviews r
  where r.artifact_version_id = p_artifact_version_id
    and r.request_id = p_request_id;

  if v_existing is not null then
    approval_status := v_version.approval_status;
    partner_review_status := v_version.partner_review_status;
    duplicate := true;
    return next;
    return;
  end if;

  -- A failed generation is not reviewable.
  if v_version.generation_status <> 'succeeded' then
    raise exception 'artifact_generation_failed' using errcode = '0A000';
  end if;

  -- A stale version cannot be approved. It stays readable and can still be
  -- rejected or have changes requested, but approval requires regeneration.
  if p_decision = 'approve' and v_version.source_drift_invalidated_at is not null then
    raise exception 'artifact_version_stale' using errcode = '55000';
  end if;

  if v_version.approval_status = 'superseded' and p_decision = 'approve' then
    raise exception 'artifact_version_superseded' using errcode = '55000';
  end if;

  insert into public.partner_onboarding_artifact_reviews (
    artifact_version_id, workspace_id, reviewer_type, reviewer_user_id,
    decision, comments, request_id
  )
  values (
    p_artifact_version_id, v_version.workspace_id, p_reviewer_type,
    p_actor_user_id, p_decision, p_comments, p_request_id
  );

  if p_reviewer_type = 'legalease' then
    -- LegalEase controls the document's own approval state and retains control
    -- of legal and platform language. The partner review state is untouched
    -- except that requesting changes routes the version back to the partner.
    -- The alias is required: this function's OUT parameters share names with
    -- these columns, so unqualified references would be ambiguous.
    update public.partner_onboarding_artifact_versions v
    set approval_status = case p_decision
          when 'approve' then 'approved'
          when 'request_changes' then 'changes_requested'
          else 'changes_requested'
        end,
        partner_visible_instructions = coalesce(
          p_partner_visible_instructions, v.partner_visible_instructions
        ),
        partner_review_status = case
          when p_decision = 'approve' and v.partner_review_status = 'not_requested'
            then 'awaiting_partner'
          else v.partner_review_status
        end
    where v.id = p_artifact_version_id
    returning v.* into v_version;
  else
    -- The partner approves only partner-owned factual and branding content. It
    -- cannot move approval_status, publish, or activate anything.
    update public.partner_onboarding_artifact_versions v
    set partner_review_status = case p_decision
          when 'approve' then 'approved'
          else 'changes_requested'
        end
    where v.id = p_artifact_version_id
    returning v.* into v_version;
  end if;

  update public.partner_onboarding_artifacts
  set lifecycle_status = case
        when v_version.approval_status = 'approved' then 'approved'
        when v_version.approval_status = 'changes_requested' then 'in_review'
        else lifecycle_status
      end
  where id = v_artifact.id;

  insert into public.partner_onboarding_activity (
    workspace_id, event_type, owner_type, summary_code, status_code,
    artifact_version_id
  )
  values (
    v_version.workspace_id,
    case
      when p_reviewer_type = 'partner' then 'artifact_partner_reviewed'
      when p_decision = 'approve' then 'artifact_approved'
      else 'artifact_changes_requested'
    end,
    case when p_reviewer_type = 'partner' then 'partner' else 'legalease' end,
    v_artifact.artifact_type,
    p_decision,
    p_artifact_version_id
  )
  on conflict do nothing;

  approval_status := v_version.approval_status;
  partner_review_status := v_version.partner_review_status;
  duplicate := false;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.rcap_service_stage_real_launch(p_slug text, p_actor uuid, p_operation uuid, p_version bigint, p_hash text, p_versions jsonb, p_authority uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare w public.partner_onboarding%rowtype; a public.rcap_commercial_authorizations%rowtype; consent public.partner_onboarding_launch_approvals%rowtype; final_review public.partner_onboarding_launch_approvals%rowtype; begin
 perform public.rcap_service_assert_internal_actor(p_actor);
 select * into strict w from public.partner_onboarding where partner_slug=p_slug for update;
 perform 1 from public.partner_records where id=w.partner_record_id for update;
 perform 1 from public.partner_onboarding_sections where workspace_id=w.id for update;
 perform 1 from public.partner_onboarding_assets where workspace_id=w.id for update;
 perform 1 from public.partner_onboarding_artifacts where workspace_id=w.id for update;
 perform 1 from public.partner_onboarding_artifact_versions where workspace_id=w.id for update;
 perform 1 from public.partner_onboarding_launch_checks where workspace_id=w.id for update;
 perform 1 from public.partner_onboarding_launch_approvals where workspace_id=w.id for update;
 select * into strict a from public.rcap_commercial_authorizations where id=p_authority and workspace_id=w.id;
 if w.status='live' or w.landing_page_ready or w.aggregate_version<>p_version or w.agreement_status<>'signed' or w.commercial_gate_status='blocked' then raise exception 'stale or unapproved publication source' using errcode='40001'; end if;
 if not exists(select 1 from public.rcap_launch_operation_events where workspace_id=w.id and operation_id=p_operation and actor_auth_user_id=p_actor and snapshot_hash=p_hash and step='prepared' and evidence->>'mode'='real' and evidence->>'commercialAuthorityId'=a.id::text) then raise exception 'matching real launch authorization required'; end if;
 if exists(select 1 from public.rcap_launch_capacity_events ce where ce.workspace_id=w.id and ce.created_at>a.created_at) then raise exception 'renew commercial authorization after capacity changes';end if;
 if a.expires_at<=now() or not exists(select 1 from public.partner_onboarding_assets where id=a.document_id and workspace_id=w.id and sha256_hex=a.document_hash and lifecycle_status='active' and review_status='approved') then raise exception 'commercial authority expired or withdrawn'; end if;
 if exists(select 1 from public.partner_records r join public.rcap_launch_operation_events e on e.workspace_id=w.id and e.operation_id=p_operation and e.step='prepared' where r.id=w.partner_record_id and ((e.evidence->'snapshot'->'activationRecord'->>'payment_status') is distinct from r.payment_status or (e.evidence->'snapshot'->'activationRecord'->>'stripe_payment_intent_id') is distinct from r.stripe_payment_intent_id or (e.evidence->'snapshot'->'activationRecord'->>'paid_at')::timestamptz is distinct from r.paid_at or (e.evidence->'snapshot'->'activationRecord'->>'payment_amount')::numeric is distinct from r.payment_amount or (e.evidence->'snapshot'->'activationRecord'->>'qualification_status') is distinct from r.qualification_status)) then raise exception 'financial or activation source changed after snapshot';end if;
 if not exists(select 1 from public.partner_records r where r.id=w.partner_record_id and r.qualification_status='qualified' and r.payment_status is distinct from 'demo_paid' and r.provisioning_status in ('active','provisioned') and r.access_mode=a.access_mode and (a.kind<>'verified_paid' or (r.payment_status='paid' and r.stripe_payment_intent_id ~ '^pi_[A-Za-z0-9]+$' and r.paid_at<=now() and r.payment_amount>0))) then raise exception 'activation or payment authority changed'; end if;
 if (select count(*) from public.partner_onboarding_sections where workspace_id=w.id and status='approved')<>8 or not exists(select 1 from public.partner_onboarding_sections where workspace_id=w.id and section_key='access_sponsorship_capacity' and response_data->>'participant_access_model'=a.access_mode) then raise exception 'canonical configuration unapproved or conflicting'; end if;
 if not exists(select 1 from public.partner_onboarding_sections geo join public.partner_records r on r.id=w.partner_record_id join public.rcap_launch_operation_events e on e.operation_id=p_operation and e.step='prepared' where geo.workspace_id=w.id and geo.section_key='geography_audience_language_accessibility' and geo.status='approved' and case when jsonb_array_length(geo.response_data->'jurisdictions')=1 then geo.response_data->'jurisdictions'->>0 else case when geo.response_data->'jurisdictions' ? coalesce(r.target_state,r.state) then coalesce(r.target_state,r.state) end end=e.evidence->>'intakeJurisdiction') then raise exception 'approved primary screening jurisdiction changed or absent';end if;
 perform 1 from public.partner_entitlement where partner_slug=p_slug for update;
 if not exists(select 1 from public.partner_entitlement where partner_slug=p_slug and screenings_allowed>screenings_used) then raise exception 'screening allocation exhausted or absent'; end if;
 perform 1 from public.partner_packet_entitlement where id=a.packet_entitlement_id for update;
 if not exists(select 1 from public.partner_packet_entitlement e where e.id=a.packet_entitlement_id and e.partner_id=w.partner_record_id and e.effective_at<=now() and (e.expires_at is null or e.expires_at>now()) and e.packet_cap>(select count(*) from public.packet_credit_ledger l where l.entitlement_id=e.id and l.event_type='consumed')) then raise exception 'packet allocation exhausted or absent'; end if;
 select * into consent from public.partner_onboarding_launch_approvals where workspace_id=w.id and approval_type='partner_launch_approval' order by recorded_at desc,id desc limit 1;
 select * into final_review from public.partner_onboarding_launch_approvals where workspace_id=w.id and approval_type='legalease_final_review' order by recorded_at desc,id desc limit 1;
 if consent.id is null or consent.decision<>'approve' or consent.invalidated_at is not null or not exists(select 1 from public.partner_users where auth_user_id=consent.reviewer_user_id and partner_slug=p_slug and role='partner_admin' and status='active') or final_review.id is null or final_review.decision<>'approve' or final_review.invalidated_at is not null then raise exception 'current partner consent and final review required'; end if;
 perform public.rcap_service_assert_internal_actor(final_review.reviewer_user_id);
 if not exists(select 1 from public.partner_onboarding_launch_checks where workspace_id=w.id and check_key='staff_training_completed' and status='passing' and invalidated_at is null) then raise exception 'current training review required'; end if;
 if jsonb_typeof(p_versions)<>'array' or jsonb_array_length(p_versions)<>5 or (select count(distinct item->>'type') from jsonb_array_elements(p_versions) item)<>5 then raise exception 'exact five-material package required'; end if;
 if exists(select 1 from jsonb_array_elements(p_versions) item where not exists(select 1 from public.partner_onboarding_artifact_versions v join public.partner_onboarding_artifacts ar on ar.id=v.artifact_id where v.workspace_id=w.id and v.id=(item->>'id')::uuid and ar.current_version_id=v.id and ar.artifact_type=item->>'type' and ar.artifact_type in ('implementation_brief','operations_escalation_plan','dashboard_user_reporting_matrix','staff_quick_start_guide','co_branded_page_configuration') and v.snapshot_hash=item->>'hash' and item->>'freshness'='current' and v.approval_status='approved' and v.generation_status='succeeded' and v.superseded_at is null and v.source_drift_invalidated_at is null and (ar.artifact_type not in ('implementation_brief','co_branded_page_configuration') or v.partner_review_status='approved'))) then raise exception 'approved package changed' using errcode='40001'; end if;
 if exists(select 1 from public.rcap_launch_operation_events e cross join lateral jsonb_array_elements(e.evidence->'checks') c where e.operation_id=p_operation and e.step='prepared' and exists(select 1 from public.partner_onboarding_launch_checks lc where lc.workspace_id=w.id and lc.check_key=c->>'key' and (lc.status<>c->>'status' or lc.invalidated_at is not null or lc.checked_at is distinct from (c->>'checkedAt')::timestamptz))) then raise exception 'recorded checks changed after snapshot'; end if;
 update public.partner_records set onboarding_status='approved',onboarding_completed_at=coalesce(onboarding_completed_at,now()) where id=w.partner_record_id;
 update public.partner_onboarding set status='live' ,landing_page_ready=true,internal_approved_at=now(),launched_at=now(),rcap_launch_operation_id=p_operation where id=w.id;
 insert into public.rcap_launch_operation_events(workspace_id,partner_slug,operation_id,request_id,step,actor_auth_user_id,snapshot_hash,authority_reference,evidence)
 select workspace_id,partner_slug,operation_id,request_id,'publication_staged',actor_auth_user_id,snapshot_hash,authority_reference,jsonb_build_object('mode','real','commercialAuthorityId',a.id,'workspaceVersion',p_version) from public.rcap_launch_operation_events where workspace_id=w.id and operation_id=p_operation and step='prepared';
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.rcap_service_stage_synthetic_launch(p_slug text, p_actor uuid, p_operation uuid, p_version bigint, p_hash text, p_versions jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_workspace public.partner_onboarding%rowtype; begin
 perform public.rcap_service_assert_internal_actor(p_actor);
 if not exists(select 1 from public.rcap_synthetic_launch_targets t join public.partner_users u on u.auth_user_id=t.registered_by where t.partner_slug=p_slug and u.role='internal_admin' and u.status='active' and u.partner_slug is null) then raise exception 'registered synthetic target required' using errcode='42501'; end if;
 select * into strict v_workspace from public.partner_onboarding where partner_slug=p_slug for update;
 if v_workspace.status='live' then raise exception 'already published' using errcode='40001'; end if;
 if v_workspace.aggregate_version<>p_version then raise exception 'stale launch source' using errcode='40001'; end if;
 if not exists(select 1 from public.rcap_launch_operation_events where workspace_id=v_workspace.id and operation_id=p_operation and actor_auth_user_id=p_actor and snapshot_hash=p_hash and step='prepared') then raise exception 'matching prepared authority required' using errcode='42501'; end if;
 if not exists(select 1 from public.partner_records where partner_slug=p_slug and payment_status in ('paid','demo_paid') and qualification_status='qualified' and provisioning_status in ('provisioned','active')) then raise exception 'existing activation authority required' using errcode='42501'; end if;
 if not exists(select 1 from public.partner_entitlement where partner_slug=p_slug and screenings_allowed>screenings_used) then raise exception 'screening capacity required' using errcode='42501'; end if;
 if v_workspace.commercial_gate_status='blocked' or v_workspace.agreement_status<>'signed' then raise exception 'commercial and contractual authority required' using errcode='42501'; end if;
 if jsonb_typeof(p_versions)<>'array' or jsonb_array_length(p_versions)<>5 or (select count(distinct item->>'id') from jsonb_array_elements(p_versions) item)<>5 then raise exception 'exact package required'; end if;
 if exists(select 1 from jsonb_array_elements(p_versions) item where not exists(select 1 from public.partner_onboarding_artifact_versions v join public.partner_onboarding_artifacts a on a.id=v.artifact_id where v.workspace_id=v_workspace.id and v.id=(item->>'id')::uuid and a.current_version_id=v.id and v.snapshot_hash=item->>'hash' and v.approval_status='approved' and v.generation_status='succeeded' and v.superseded_at is null and v.source_drift_invalidated_at is null and (a.artifact_type not in ('implementation_brief','co_branded_page_configuration') or v.partner_review_status='approved'))) then raise exception 'package changed' using errcode='40001'; end if;
 update public.partner_onboarding set status='live',landing_page_ready=true,internal_approved_at=now(),launched_at=now() where id=v_workspace.id;
 insert into public.rcap_launch_operation_events(workspace_id,partner_slug,operation_id,request_id,step,actor_auth_user_id,snapshot_hash,authority_reference,evidence)
 select workspace_id,partner_slug,operation_id,request_id,'publication_staged',actor_auth_user_id,snapshot_hash,authority_reference,jsonb_build_object('workspaceVersion',p_version) from public.rcap_launch_operation_events where workspace_id=v_workspace.id and operation_id=p_operation and step='prepared';
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.rcap_service_supersede_onboarding_artifact_version(p_partner_slug text, p_actor_user_id uuid, p_artifact_version_id uuid)
 RETURNS TABLE(superseded boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_updated public.partner_onboarding_artifact_versions%rowtype;
  v_artifact_type text;
begin
  update public.partner_onboarding_artifact_versions v
  set approval_status = 'superseded',
      superseded_at = now()
  from public.partner_onboarding po
  where v.id = p_artifact_version_id
    and po.id = v.workspace_id
    and po.partner_slug = p_partner_slug
    and v.superseded_at is null
    and v.generation_status = 'succeeded'
  returning v.* into v_updated;

  if v_updated.id is null then
    superseded := false;
    return next;
    return;
  end if;

  select a.artifact_type into v_artifact_type
  from public.partner_onboarding_artifacts a
  where a.id = v_updated.artifact_id;

  update public.partner_onboarding_artifacts
  set lifecycle_status = 'superseded'
  where id = v_updated.artifact_id
    and current_version_id = v_updated.id;

  insert into public.partner_onboarding_activity (
    workspace_id, event_type, owner_type, summary_code, status_code,
    artifact_version_id
  )
  values (
    v_updated.workspace_id, 'artifact_superseded', 'legalease',
    v_artifact_type, 'superseded', v_updated.id
  )
  on conflict do nothing;

  superseded := true;
  return next;
end;
$function$
